tool_input.old_string:
/** 打开外部 H5：苏服办 H5 整页跳转（与不动产授权一致），非 H5 走内嵌 webView */
export function navigateToExternalUrl(absoluteUrl) {
  const u = `${absoluteUrl || ''}`.trim()
  if (!u) return Promise.resolve(false)

  const result = resolveWebViewUrl(u)
  if (!result.ok) {
    uni.showToast({ title: result.message, icon: 'none' })
    return Promise.resolve(false)
  }

  /* #ifdef H5 */
  window.location.replace(result.url)
  return Promise.resolve(true)
  /* #endif */

  /* #ifndef H5 */
  return new Promise((resolve) => {
    uni.navigateTo({
      url: `/pages/common/webView?url=${encodeURIComponent(result.url)}`,
      success: () => resolve(true),
      fail: () => {
        uni.showToast({ title: '跳转失败，请重试', icon: 'none' })
        resolve(false)
      },
    })
  })
  /* #endif */
}

tool_input.new_string:
/** 打开外部 H5。苏服办用容器 navigation.show；没有该接口时整页跳转。返回是否已发起打开。 */
export function navigateToExternalUrl(absoluteUrl) {
  const u = `${absoluteUrl || ''}`.trim()
  if (!u) return Promise.resolve(false)

  const result = resolveWebViewUrl(u)
  if (!result.ok) return Promise.resolve(false)

  /* #ifdef H5 */
  const show = window.lightAppJssdk?.navigation?.show
  if (typeof show === 'function') {
    return new Promise((resolve) => {
      let settled = false
      const finish = (ok) => {
        if (settled) return
        settled = true
        resolve(ok)
      }
      const timer = setTimeout(() => finish(false), 8000)
      try {
        show({
          url: result.url,
          title: '业主决策',
          isgoback: '0',
          success: () => {
            clearTimeout(timer)
            finish(true)
          },
          fail: () => {
            clearTimeout(timer)
            finish(false)
          },
        })
      } catch (e) {
        clearTimeout(timer)
        finish(false)
      }
    })
  }
  window.location.replace(result.url)
  return Promise.resolve(true)
  /* #endif */

  /* #ifndef H5 */
  return new Promise((resolve) => {
    uni.navigateTo({
      url: `/pages/common/webView?url=${encodeURIComponent(result.url)}`,
      success: () => resolve(true),
      fail: () => resolve(false),
    })
  })
  /* #endif */
}

